// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _target, uint256 _value) public {
        // Bound to reasonable values to avoid trivial revert
        _value = bound(_value, 1, 1e18);
        vm.assume(_target != address(0));

        uint256 beforeDeposits = c.depositsCount();
        (bool success, ) = address(c).call{value: _value}("");
        // If the test is on the reference, the fallback increments depositsCount.
        // But we need to ensure we call sendMoney which triggers the fallback.
        // So we call sendMoney directly:
        c.sendMoney(_target, _value);

        uint256 afterDeposits = c.depositsCount();

        // The rule: depositsCount must increase by exactly 1, because sendMoney triggers the fallback once.
        assertTrue(afterDeposits == beforeDeposits + 1, "depositsCount should increment by 1 after sendMoney");
    }
}

